def _source_manifest(graph: dict[str, Any]) -> list[dict[str, Any]]:
    return sorted(
        [
            {
                "entity_id": entity["id"],
                "commit": entity["commit"],
                "blob": entity["blob"],
                "path": entity["path"],
                "start_byte": entity["range"]["start_byte"],
                "end_byte": entity["range"]["end_byte"],
                "start_line": entity["range"]["start_line"],
                "end_line": entity["range"]["end_line"],
            }
            for entity in graph.get("entities", [])
        ],
        key=lambda item: item["entity_id"],
    )

def audit_facts_layer(output: Path, graph: dict[str, Any] | None = None) -> dict[str, Any]:
    graph = graph or json_load(output / "graph.json")
    root = output / "facts"
    errors: list[dict[str, Any]] = []
    required = ("graph.json", "source-manifest.json", "review-manifest.json", "manifest.json")
    for name in required:
        if not (root / name).is_file():
            errors.append({"reason": "facts-file-missing", "path": name})
    if not errors:
        if (root / "graph.json").read_bytes() != (output / "graph.json").read_bytes():
            errors.append({"reason": "facts-graph-differs-from-root-graph"})
        source_manifest = json_load(root / "source-manifest.json")
        if source_manifest != _source_manifest(graph):
            errors.append({"reason": "facts-source-manifest-mismatch"})
        manifest = json_load(root / "manifest.json")
        expected_counts = {
            "entities": len(graph.get("entities", [])),
            "relations": len(graph.get("links", [])),
            "providers": len(graph.get("providers", [])),
            "review_packs": len(json_load(root / "review-manifest.json")),
        }
        if manifest.get("counts") != expected_counts:
            errors.append({"reason": "facts-count-mismatch", "actual": manifest.get("counts"), "expected": expected_counts})
    result = {
        "schema_version": FACTS_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
        "root": str(root.resolve()),
        "errors": errors,
    }
    json_write(root / "audit.json", result)
    return result

def _copy_file(source: Path, target: Path) -> None:
    target.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(source, target)

def _generated_files(markdown: Path) -> list[str]:
    ownership = markdown / ".ckb-generated-files.json"
    if not ownership.is_file():
        raise CkbError("Markdown generated ownership is missing")
    return [str(value) for value in json_load(ownership).get("files", [])]

def audit_human_layer(output: Path, graph: dict[str, Any] | None = None) -> dict[str, Any]:
    graph = graph or json_load(output / "graph.json")
    markdown = output / "markdown"
    human = output / "human"
    errors: list[dict[str, Any]] = []
    ignored_user_state_differences: list[str] = []
    if not human.is_dir():
        errors.append({"reason": "human-root-missing"})
    elif not (human / "manifest.json").is_file():
        errors.append({"reason": "human-manifest-missing"})
    if not errors:
        for relative in _generated_files(markdown):
            left = markdown / relative
            right = human / relative
            differs = left.is_file() and (not right.is_file() or left.read_bytes() != right.read_bytes())
            if str(relative).replace("\\", "/").startswith(".obsidian/"):
                if differs:
                    ignored_user_state_differences.append(str(relative).replace("\\", "/"))
                continue
            if differs:
                errors.append({"reason": "human-markdown-parity", "path": relative})
        for directory in NOTE_DIRECTORIES:
            markdown_notes = {path.name: path.read_bytes() for path in (markdown / directory).glob("*.md")}
            human_notes = {path.name: path.read_bytes() for path in (human / directory).glob("*.md")}
            if markdown_notes != human_notes:
                errors.append({"reason": "human-note-parity", "directory": directory})
        for directory in FEEDBACK_DIRECTORIES:
            markdown_feedback = {path.name: path.read_bytes() for path in (markdown / directory).glob("*.md")}
            human_feedback = {path.name: path.read_bytes() for path in (human / directory).glob("*.md")}
            if markdown_feedback != human_feedback:
                errors.append({"reason": "human-feedback-parity", "directory": directory})
        readability = json_load(human / "readability-audit.json") if (human / "readability-audit.json").is_file() else {}
        if readability.get("status") != "passed":
            errors.append({"reason": "human-readability-not-passed", "detail": readability})
    language_errors: list[dict[str, Any]] = []
    for entity in graph.get("entities", []):
        if entity.get("classification") == "appendix":
            if not contains_chinese_narrative(entity.get("description_zh")):
                language_errors.append({"entity_id": entity["id"], "field": "description_zh"})
        else:
            for field in ("meaning_zh", "role_zh", "change_when_zh"):
                if not contains_chinese_narrative(entity.get(field)):
                    language_errors.append({"entity_id": entity["id"], "field": field})
    if language_errors:
        errors.append({"reason": "human-chinese-description-contract", "detail": language_errors})
    result = {
        "schema_version": HUMAN_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
        "root": str(human.resolve()),
        "compatibility_root": str(markdown.resolve()),
        "language": "zh-CN",
        "ignored_user_state_differences": sorted(ignored_user_state_differences),
        "errors": errors,
    }
    if human.is_dir():
        json_write(human / "audit.json", result)
    return result

def mirror_note(output: Path, relative: Path) -> None:
    """Copy one Agent/user note between the legacy and dedicated human roots."""
    markdown = output / "markdown" / relative
    human = output / "human" / relative
    if markdown.is_file():
        _copy_file(markdown, human)
    elif human.is_file():
        _copy_file(human, markdown)

def write_capability_matrix(path: Path, format_name: str) -> dict[str, Any]:
    path = path.resolve()
    if path.exists():
        raise CkbError(f"capability matrix target already exists: {path}")
    path.parent.mkdir(parents=True, exist_ok=True)
    if format_name == "markdown":
        path.write_text(render_capability_matrix_markdown(), encoding="utf-8", newline="\n")
    else:
        json_write(path, capability_matrix())
    return {"schema_version": 1, "status": "written", "format": format_name, "path": str(path)}

def contains_chinese_narrative(value: Any, minimum_han: int = 2) -> bool:
    """Require Chinese prose while allowing identifiers and foreign terms."""
    if not isinstance(value, str) or len(value.strip()) < 4:
        return False
    return len(re.findall(r"[\u3400-\u9fff]", value)) >= minimum_han

def _fts_query_values(values: Iterable[str]) -> str | None:
    values = [term for term in values if len(term) >= 3][:16]
    if not values:
        return None
    return " OR ".join('"' + value.replace('"', '""') + '"' for value in values)

def _human_projection(output: Path) -> tuple[dict[str, Any], Path]:
    for root in (output / "human", output / "markdown"):
        path = root / "projection.json"
        if path.is_file():
            return json_load(path), root
    logseq = output / "logseq-db/projection.json"
    if logseq.is_file():
        return json_load(logseq), output / "logseq-db"
    raise CkbError("machine knowledge requires a completed human projection")

def _note_documents(root: Path) -> list[dict[str, Any]]:
    if not root.is_dir():
        return []
    result: list[dict[str, Any]] = []
    kinds = {
        "analysis": "analysis",
        "changes": "change",
        "pitfalls": "pitfall",
        "experiments": "experiment",
        "sessions": "session",
    }
    for directory in NOTE_DIRECTORIES:
        for path in sorted((root / directory).glob("*.md")):
            content = path.read_text(encoding="utf-8")
            title = content.splitlines()[0].removeprefix("# ").strip() if content else path.stem
            tag = next(iter(re.findall(r"#类型/[\w\u3400-\u9fff-]+", content)), "")
            result.append(
                {
                    "id": f"note:{directory}:{path.stem}",
                    "kind": kinds[directory],
                    "title": title,
                    "tag": tag,
                    "relative_path": path.relative_to(root).as_posix(),
                    "content": content,
                    "links": re.findall(r"\[\[([^\]|#]+)", content),
                }
            )
    return result

def _review_paths(output: Path) -> dict[str, str]:
    result: dict[str, str] = {}
    state_path = output / "state.json"
    if not state_path.is_file():
        return result
    state = json_load(state_path)
    for pack in state.get("review_packs", []):
        path = pack.get("review_path")
        if not path or not Path(path).is_file():
            continue
        for item in json_load(Path(path)).get("reviews", []):
            result[str(item.get("entity_id"))] = str(Path(path).resolve())
    return result

def _source_texts(output: Path, graph: dict[str, Any]) -> dict[str, str]:
    state = json_load(output / "state.json")
    snapshot = state.get("source_snapshot") or {}
    root = Path(snapshot.get("root", ""))
    texts: dict[str, str] = {}
    for path in sorted({str(entity["path"]) for entity in graph.get("entities", [])}):
        source = root / Path(path)
        if source.is_file():
            texts[path] = source.read_text(encoding="utf-8", errors="replace")
    return texts

def _description(entity: dict[str, Any]) -> str:
    if entity.get("classification") == "appendix":
        return str(entity.get("description_zh") or "").strip()
    return " ".join(
        str(entity.get(field) or "").strip()
        for field in ("meaning_zh", "role_zh", "change_when_zh")
        if str(entity.get(field) or "").strip()
    )

def _human_map(logical: dict[str, Any], projection: dict[str, Any]) -> tuple[dict[str, str], dict[str, dict[str, Any]]]:
    owners = dict(logical.get("entity_owner_pages", {})) if logical else dict(projection.get("entity_owner_pages", {}))
    pages = {str(page["id"]): page for page in projection.get("pages", [])}
    return owners, pages

def _sections_for_entity(entity: dict[str, Any], excerpt: str) -> list[tuple[str, str]]:
    sections: list[tuple[str, str]] = []
    if entity.get("classification") == "appendix":
        sections.append(("中文作用", str(entity.get("description_zh") or "").strip()))
    else:
        sections.extend(
            [
                ("中文含义", str(entity.get("meaning_zh") or "").strip()),
                ("中文职责", str(entity.get("role_zh") or "").strip()),
                ("什么时候需要修改", str(entity.get("change_when_zh") or "").strip()),
            ]
        )
    sections.append(("来源核对", str(entity.get("evidence_note") or "").strip()))
    if entity.get("kind") != "file" and excerpt.strip():
        bounded = excerpt.strip()
        if len(bounded) > 3600:
            bounded = bounded[:3600].rstrip() + "\n\n……源码摘录已截断；完整文件保存在机器库 source_files 表中。"
        sections.append(("固定源码摘录", bounded))
    return [(heading, content) for heading, content in sections if content]

